1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { seaMap } from "@pirate-sea-race/content";
3	import { objectiveRules } from "@pirate-sea-race/simulation/objectives";
4	import { clueFor, findRuin, sessionOf } from "@pirate-sea-race/simulation/ruins";
5	import { checkLedger } from "@pirate-sea-race/simulation/objectives";
6	import { MAX_RUIN_MESSAGES_PER_SECOND, parseRuinResultMessage, RuinMessageType, TEST_NEXT_MATCH_RUINS_PATH } from "@pirate-sea-race/protocol";
7	import { startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
8	import { HeadlessClient, ImpairmentProxy, readClue, sleep, wrongAnswer, type ReadClue } from "@pirate-sea-race/test-tools";
9	import { containsText, EAST, HOLD_E, openWater, playersAt, quickStart, roomOf, startThroughLobby, tracker, until, type Seat } from "./seaDuelSetup.js";
10	import { layout, quickEncounters } from "./rubbingsSetup.js";
11	
12	/**
13	 * The ruins in the match room (§3, §11, §16): every island's sources start locked behind its ruin; a player moored
14	 * there opens it, reads the clue and answers; the first solve unlocks the island for everyone, and every solver earns
15	 * 40 gold once. The server pins Palm Key's ruin to a sequence and Ember Rock's to a grid (test-only), leaves Old Stones
16	 * dealt from the ruins' own seed, locked, and opens Mist Cay from the start. Answers are worked out from the clue the client
17	 * received, as a reader would (`readClue`). Every test's rooms check `checkLedger` and the room's invariant after
18	 * every world tick, and that the ledger refused nothing the room asked (`tracker`).
19	 */
20	let server: RunningGameServer;
21	let endpoint: string;
22	
23	beforeAll(async () => {
24	  const matchTuning = quickStart({
25	    sourceLayout: layout,
26	    objectives: { ...objectiveRules, collectTicks: 20 },
27	    encounters: quickEncounters,
28	    testRuins: { "0": "sequence", "1": "navigation", "3": "open" },
29	    // The room's test-only fault, to end a match.
30	    testHooks: true,
31	  });
32	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false, testPlacement: true, matchTuning });
33	  endpoint = `http://127.0.0.1:${server.port}`;
34	});
35	
36	afterAll(async () => {
37	  await server.close();
38	});
39	
40	const docksOf = (island: number) => seaMap.docks.filter((dock) => dock.island === island);
41	const PALM = docksOf(0);
42	const EMBER = docksOf(1);
43	const LOCKOUT_TICKS = 60;
44	/** Somewhere at sea off Palm Key's west dock, in sight of it. */
45	const OFF_PALM: Seat = { tileX: PALM[0]!.tileX - 4, tileY: PALM[0]!.tileY, heading: EAST };
46	
47	/** Moors a player at a dock: placed on it, then E held until the ship is moored (a locked island gives E nothing more). */
48	async function moor(client: HeadlessClient, dock: { id: number; tileX: number; tileY: number }): Promise<void> {
49	  await client.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY, heading: 0 });
50	  await client.holdUntil(HOLD_E, () => client.ship()?.dock === dock.id, 5000);
51	}
52	
53	/** Opens the ruin where the player is moored and resolves with the clue it received. */
54	async function open(client: HeadlessClient): Promise<ReadClue> {
55	  const before = client.clues.length;
56	  client.openRuin();
57	  await client.waitFor(() => client.clues.length > before && client.ruinView()?.ruinOpen === true, 3000);
58	  return client.clues.at(-1)!.clue;
59	}
60	
61	/** Answers and resolves with the verdict. */
62	async function answer(client: HeadlessClient, attempt: Parameters<HeadlessClient["answerRuin"]>[0], requestId?: string) {
63	  const after = client.ruinResults.length;
64	  const id = client.answerRuin(attempt, requestId);
65	  return client.ruinResult(id, 3000, after);
66	}
67	
68	async function pairAt(track: (client: HeadlessClient) => void, seats: readonly Seat[] = [OFF_PALM, { ...OFF_PALM, tileY: OFF_PALM.tileY - 2 }]) {
69	  const [host, guest] = (await playersAt(endpoint, seats, track)) as [HeadlessClient, HeadlessClient];
70	  return { host, guest, room: roomOf(host) };
71	}
72	
73	describe.concurrent("the ruins in the match room (§3, §11)", () => {
74	  it("locks every source at the start, refuses collection until the island's ruin is solved, and the first solve unlocks it for everyone, once", async ({ onTestFinished }) => {
75	    const track = tracker(onTestFinished);
76	    const { host, guest, room } = await pairAt(track);
77	    // Every source is locked but Mist Cay's, which this server opens from the start (test-only).
78	    expect(room.ledgerState.sources.filter((source) => source.unlocked).map((source) => source.island)).toEqual([3, 3]);
79	    await moor(host, PALM[0]!);
80	    await moor(guest, PALM[1]!);
81	    // Holding E at a locked island collects nothing: no target, no hold, however long.
82	    await host.holdUntil(HOLD_E, () => false, 1500).catch(() => undefined);
83	    expect(host.rubbings()).toEqual([]);
84	    expect(host.objectives()).toMatchObject({ target: "", channel: "", islandTypes: ["sun", "sun"] });
85	    expect(room.ledgerState.players.every((player) => player.channel === null)).toBe(true);
86	    expect(host.ruinView()).toEqual({ ruin: "locked", ruinOpen: false, ruinLockedUntil: 0 });
87	    expect(guest.ruinMarkers().find((marker) => marker.island === 0)?.unlocked).toBe(false);
88	
89	    const clue = await open(host);
90	    expect(clue.kind).toBe("sequence");
91	    const solved = await answer(host, readClue(clue));
92	    expect(solved).toMatchObject({ outcome: "solved", island: 0, gold: 40, unlocked: true, reason: null });
93	    // The island's two sources, and only those, are open, for everyone.
94	    expect(room.ledgerState.sources.filter((source) => source.unlocked).map((source) => source.id)).toEqual(["source-0-0", "source-0-1", "source-3-0", "source-3-1"]);
95	    await guest.waitFor(() => guest.ruinView()?.ruin === "unlocked" && guest.ruinMarkers().find((marker) => marker.island === 0)?.unlocked === true);
96	    await host.waitFor(() => host.ruinView()?.ruin === "solved");
97	    expect(guest.objectives()?.target).toBe("collect:sun");
98	    // The guest, who solved nothing, collects; so does the host.
99	    await guest.holdUntil(HOLD_E, () => guest.rubbings().includes("sun"), 8000);
100	    await host.holdUntil(HOLD_E, () => host.rubbings().includes("sun"), 8000);
101	    // Once: a second solve (the guest's) unlocks nothing more.
102	    const second = await answer(guest, readClue(await open(guest)));
103	    expect(second).toMatchObject({ outcome: "solved", gold: 40, unlocked: false });
104	    expect(room.ledgerState.sources.filter((source) => source.unlocked)).toHaveLength(4);
105	    expect(checkLedger(room.ledgerState)).toEqual([]);
106	  }, 30_000);
107	
108	  it("pays every solver 40 once, through the ledger's grant: a second solver their own, a repeat nothing, and a retried request its first verdict", async ({ onTestFinished }) => {
109	    const track = tracker(onTestFinished);
110	    const { host, guest, room } = await pairAt(track);
111	    await moor(host, PALM[0]!);
112	    await moor(guest, PALM[1]!);
113	    const [hostGold, guestGold] = [host.gold(), guest.gold()];
114	    const clue = await open(host);
115	    const first = await answer(host, readClue(clue), "first");
116	    expect(first).toMatchObject({ outcome: "solved", gold: 40 });
117	    await host.waitFor(() => host.gold() === hostGold + 40);
118	    // The same request again: the first verdict, judged once, paid once.
119	    const retried = await answer(host, readClue(clue), "first");
120	    expect(retried).toEqual(first);
121	    // A new request after solving: refused, nothing paid.
122	    const repeat = await answer(host, readClue(clue));
123	    expect(repeat).toMatchObject({ outcome: "refused", reason: "already-solved", gold: 0, unlocked: false });
124	    const own = await answer(guest, readClue(await open(guest)));
125	    expect(own).toMatchObject({ outcome: "solved", gold: 40, unlocked: false });
126	    await guest.waitFor(() => guest.gold() === guestGold + 40);
127	    await sleep(200);
128	    expect(host.gold()).toBe(hostGold + 40);
129	    const grants = room.ledgerState.grants.map(({ reason, sourceKey, playerId, amount }) => ({ reason, sourceKey, playerId, amount }));
130	    expect(grants).toEqual([
131	      { reason: "ruin", sourceKey: "0", playerId: host.sessionId, amount: 40 },
132	      { reason: "ruin", sourceKey: "0", playerId: guest.sessionId, amount: 40 },
133	    ]);
134	    expect(checkLedger(room.ledgerState)).toEqual([]);
135	  }, 30_000);
136	
137	  it("locks a wrong answer out for 3 s, that player only; leaving and reopening keeps the lockout", async ({ onTestFinished }) => {
138	    const track = tracker(onTestFinished);
139	    const { host, guest, room } = await pairAt(track);
140	    await moor(host, EMBER[0]!);
141	    await moor(guest, EMBER[1]!);
142	    const clue = await open(host);
143	    expect(clue.kind).toBe("navigation");
144	    const wrong = await answer(host, wrongAnswer(clue));
145	    expect(wrong.outcome).toBe("wrong");
146	    expect(wrong.gold).toBe(0);
147	    const until = wrong.lockedUntil;
148	    expect(until).toBeGreaterThanOrEqual(LOCKOUT_TICKS);
149	    await host.waitFor(() => host.ruinView()?.ruinLockedUntil === until);
150	    // The right answer during the lockout is refused, and does not extend it.
151	    expect(await answer(host, readClue(clue))).toMatchObject({ outcome: "refused", reason: "locked-out", lockedUntil: until });
152	    // The guest is not locked out.
153	    const guestClue = await open(guest);
154	    expect(await answer(guest, readClue(guestClue))).toMatchObject({ outcome: "solved", gold: 40 });
155	    // The host casts off (the session closes), comes back and reopens: still locked out, until the same tick.
156	    await host.placeShip(endpoint, { tileX: EMBER[0]!.tileX + 4, tileY: EMBER[0]!.tileY, heading: 32 });
157	    await host.waitFor(() => host.ruinView()?.ruinOpen !== true && host.ship()?.dock === -1);
158	    await moor(host, EMBER[0]!);
159	    const reopened = host.clues.length;
160	    await open(host);
161	    expect(host.clues[reopened]).toMatchObject({ island: 1, lockedUntil: until, solved: false });
162	    if (host.worldTick < until - 5) expect(await answer(host, readClue(clue))).toMatchObject({ outcome: "refused", reason: "locked-out" });
163	    await host.waitFor(() => host.worldTick >= until, 5000);
164	    expect(await answer(host, readClue(clue))).toMatchObject({ outcome: "solved", gold: 40 });
165	    expect(room.ledgerState.grants.map((grant) => grant.playerId)).toEqual([guest.sessionId, host.sessionId]);
166	  }, 30_000);
167	
168	  it("closes a player's session when they cast off, enter a duel or disconnect", async ({ onTestFinished }) => {
169	    const track = tracker(onTestFinished);
170	    const proxy = await ImpairmentProxy.start(server.port);
171	    onTestFinished(async () => void (await proxy.close()));
172	    expect(openWater(OFF_PALM, { tileX: PALM[0]!.tileX - 1, tileY: PALM[0]!.tileY, heading: EAST })).toBe(true);
173	    // The guest never readies its arena: it loses the duel by forfeit and waits to respawn.
174	    const [host, guest, dropper] = (await playersAt(endpoint, [OFF_PALM, { ...OFF_PALM, tileY: OFF_PALM.tileY - 2 }, { ...OFF_PALM, tileY: OFF_PALM.tileY + 2 }], track, {
175	      endpoints: [endpoint, endpoint, proxy.endpoint],
176	      clients: [{}, { autoReady: false }, {}],
177	    })) as [HeadlessClient, HeadlessClient, HeadlessClient];
178	    const room = roomOf(host);
179	    const session = (id: string, island: number) => sessionOf(findRuin(room.ruinsState, island)!, id);
180	
181	    // Casting off.
182	    await moor(host, EMBER[0]!);
183	    await open(host);
184	    expect(session(host.sessionId, 1)).toBeDefined();
185	    await host.placeShip(endpoint, { tileX: EMBER[0]!.tileX + 4, tileY: EMBER[0]!.tileY, heading: 32 });
186	    await host.waitFor(() => host.ship()?.dock === -1 && host.ruinView()?.ruinOpen === false);
187	    await until(() => session(host.sessionId, 1) === undefined, 2000, "casting off closing the session");
188	    // An answer with no open ruin is refused.
189	    // (The verdict names no island, -1, which the client's parser accepts.)
190	    const atSea = await answer(host, { kind: "navigation", moves: ["N"] });
191	    expect(atSea).toMatchObject({ outcome: "refused", reason: "not-at-ruin", island: -1 });
192	    expect(parseRuinResultMessage(atSea)).toEqual(atSea);
193	
194	    // A duel: the guest, moored at Palm Key's west dock with the ruin open, is grappled from the sea.
195	    await moor(guest, PALM[0]!);
196	    await open(guest);
197	    expect(session(guest.sessionId, 0)).toBeDefined();
198	    await host.placeShip(endpoint, OFF_PALM);
199	    await host.waitFor(() => host.ship(guest.sessionId) !== undefined);
200	    host.tapGrapple();
201	    await until(() => room.encounterState.duels.some((duel) => duel.players.includes(guest.sessionId)), 5000, "the duel");
202	    await until(() => session(guest.sessionId, 0) === undefined, 2000, "the duel closing the session");
203	    await guest.waitFor(() => guest.ruinView()?.ruin === "");
204	    // Opening in a duel gives nothing, and a fighter sees no island's ruin.
205	    const clues = guest.clues.length;
206	    guest.openRuin();
207	    await guest.waitFor(() => guest.ruinMarkers().length === 0);
208	    await sleep(300);
209	    expect(guest.clues).toHaveLength(clues);
210	    // Still moored at the island while it waits to respawn (out of the world): no ruin, no clue.
211	    await guest.waitFor(() => guest.status()?.mode === "respawning", 8000);
212	    expect(room.matchState.ships.find((ship) => ship.id === guest.sessionId)?.dock).toBe(PALM[0]!.id);
213	    guest.openRuin();
214	    await sleep(300);
215	    expect(guest.clues).toHaveLength(clues);
216	    expect(room.ruinsState.presence.find((entry) => entry.playerId === guest.sessionId)).toBeUndefined();
217	
218	    // A disconnect.
219	    await moor(dropper, PALM[1]!);
220	    await open(dropper);
221	    expect(session(dropper.sessionId, 0)).toBeDefined();
222	    proxy.sever({ refuse: true });
223	    await until(() => room.ledgerState.players.find((player) => player.id === dropper.sessionId)?.status === "disconnected", 3000, "the disconnect");
224	    await until(() => session(dropper.sessionId, 0) === undefined, 1000, "the disconnect closing the session");
225	
226	    // A player who leaves: their session and presence go with them.
227	    await moor(host, EMBER[1]!);
228	    await open(host);
229	    expect(session(host.sessionId, 1)).toBeDefined();
230	    await host.leave();
231	    await until(() => room.ruinsState.presence.every((entry) => entry.playerId !== host.sessionId), 3000, "the leave closing the session");
232	    expect(session(host.sessionId, 1)).toBeUndefined();
233	  }, 45_000);
234	
235	  it("pays a solver at an island a test opened from the start, without unlocking its sources twice", async ({ onTestFinished }) => {
236	    const track = tracker(onTestFinished);
237	    const mist = docksOf(3)[0]!;
238	    const { host, room } = await pairAt(track, [
239	      { tileX: mist.tileX, tileY: mist.tileY, heading: 48 },
240	      { ...OFF_PALM, tileY: OFF_PALM.tileY - 2 },
241	    ]);
242	    expect(room.ledgerState.sources.filter((source) => source.unlocked).map((source) => source.id)).toEqual(["source-3-0", "source-3-1"]);
243	    await moor(host, mist);
244	    expect(host.ruinView()?.ruin).toBe("unlocked");
245	    expect(host.objectives()?.target).toBe("collect:moon");
246	    const gold = host.gold();
247	    const solved = await answer(host, readClue(await open(host)));
248	    expect(solved).toMatchObject({ outcome: "solved", gold: 40 });
249	    await host.waitFor(() => host.gold() === gold + 40 && host.ruinView()?.ruin === "solved");
250	    // The tracker checks the ledger refused nothing: no source was unlocked a second time.
251	    expect(room.ledgerRefusals).toEqual([]);
252	  }, 30_000);
253	
254	  it("reads no ruin message once the match has ended", async ({ onTestFinished }) => {
255	    const track = tracker(onTestFinished);
256	    const { host, room } = await pairAt(track);
257	    await moor(host, PALM[0]!);
258	    const clue = await open(host);
259	    room.injectFault();
260	    await host.waitFor(() => host.phase === "ended");
261	    const [clues, results] = [host.clues.length, host.ruinResults.length];
262	    host.openRuin();
263	    host.answerRuin(readClue(clue));
264	    await sleep(500);
265	    expect(host.clues).toHaveLength(clues);
266	    expect(host.ruinResults).toHaveLength(results);
267	    expect(room.ledgerState.grants).toEqual([]);
268	  });
269	
270	  it("gives the next match only the test-only ruins posted for it, and refuses malformed ones", async ({ onTestFinished }) => {
271	    const track = tracker(onTestFinished);
272	    const post = (body: unknown) =>
273	      fetch(`${endpoint}${TEST_NEXT_MATCH_RUINS_PATH}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
274	    expect((await post({ "0": "riddle" })).status).toBe(400);
275	    expect((await post("0=open")).status).toBe(400);
276	    expect((await post({ "0": "open" })).status).toBe(200);
277	    const next = await HeadlessClient.create(endpoint);
278	    track(next);
279	    const after = await HeadlessClient.create(endpoint);
280	    track(after);
281	    const unlocked = (client: HeadlessClient) => roomOf(client).ledgerState.sources.filter((source) => source.unlocked).map((source) => source.island);
282	    // The posted ruins replace the server's own for that match (island 0 open, nothing else), then the server's return.
283	    expect(unlocked(next)).toEqual([0, 0]);
284	    expect(unlocked(after)).toEqual([3, 3]);
285	    expect(roomOf(after).ruinsState.ruins["0"]!.puzzle.kind).toBe("sequence");
286	  });
287	
288	  it("sends the clue only to its opener and never the answer; others get only whether the island is unlocked, in sight or moored there (§16)", async ({ onTestFinished }) => {
289	    const track = tracker(onTestFinished);
290	    // The onlooker sits off Palm Key, in sight of it; the far player at Old Stones' dock sees neither Palm Key nor Ember Rock.
291	    const stones = docksOf(2)[0]!;
292	    const [opener, onlooker, far] = (await playersAt(endpoint, [OFF_PALM, { ...OFF_PALM, tileY: OFF_PALM.tileY - 2 }, { tileX: stones.tileX, tileY: stones.tileY, heading: 48 }], track)) as [HeadlessClient, HeadlessClient, HeadlessClient];
293	    const room = roomOf(opener);
294	    await moor(far, stones);
295	    await moor(opener, PALM[0]!);
296	    await onlooker.waitFor(() => onlooker.ship(opener.sessionId) !== undefined);
297	    const marks = { opener: opener.frameCount, onlooker: onlooker.frameCount, far: far.frameCount };
298	    const clue = await open(opener);
299	    const ruin = findRuin(room.ruinsState, 0)!;
300	    // Exactly the site's clue, field by field: no answer, no path length.
301	    expect(opener.clues.at(-1)).toEqual({ island: 0, clue: clueFor(ruin), lockedUntil: 0, solved: false });
302	    expect(Object.keys(clue).sort()).toEqual(["kind", "length", "tablets"]);
303	    const wrong = await answer(opener, wrongAnswer(clue));
304	    expect(wrong.outcome).toBe("wrong");
305	    expect(Object.keys(wrong).sort()).toEqual(["gold", "island", "lockedUntil", "outcome", "reason", "requestId", "unlocked"]);
306	    await opener.waitFor(() => opener.worldTick >= wrong.lockedUntil, 5000);
307	    expect((await answer(opener, readClue(clue))).outcome).toBe("solved");
308	    await onlooker.waitFor(() => onlooker.ruinMarkers().find((marker) => marker.island === 0)?.unlocked === true);
309	    await sleep(200);
310	    const openerFrames = opener.framesSince(marks.opener);
311	    expect(openerFrames.some((frame) => containsText(frame, RuinMessageType.Clue))).toBe(true);
312	    for (const secret of ["answer", "minMoves", "puzzle", "solvedBy"]) expect(openerFrames.some((frame) => containsText(frame, secret)), secret).toBe(false);
313	    for (const [name, frames] of [
314	      ["onlooker", onlooker.framesSince(marks.onlooker)],
315	      ["far", far.framesSince(marks.far)],
316	    ] as const) {
317	      for (const text of [RuinMessageType.Clue, RuinMessageType.Result, "tablets", "relation", "right-", "absent", "present", "not-at"]) {
318	        expect(frames.some((frame) => containsText(frame, text)), `${name}: ${text}`).toBe(false);
319	      }
320	    }
321	    // What the others hold of the ruins: markers (island, place, unlocked) for islands in sight or where moored, and
322	    // their own status at their own island.
323	    expect(onlooker.ruinMarkers().map((marker) => marker.island)).toContain(0);
324	    expect(onlooker.ruinMarkers().map((marker) => marker.island)).not.toContain(3);
325	    expect(onlooker.ruinView()?.ruin).toBe("");
326	    expect(far.ruinMarkers().map((marker) => marker.island)).toEqual([2]);
327	    expect(far.ruinMarkers()[0]!.unlocked).toBe(false);
328	    expect(far.ruinView()).toEqual({ ruin: "locked", ruinOpen: false, ruinLockedUntil: 0 });
329	  }, 30_000);
330	
331	  it("drops malformed and excess ruin messages, and opens nothing before the match starts", async ({ onTestFinished }) => {
332	    const track = tracker(onTestFinished);
333	    const host = await HeadlessClient.create(endpoint);
334	    track(host);
335	    // In the lobby: no clue.
336	    host.openRuin();
337	    await sleep(300);
338	    expect(host.clues).toEqual([]);
339	    const bench = await startThroughLobby(endpoint, [host]);
340	    track(bench!);
341	    await host.placeShip(endpoint, OFF_PALM);
342	    await moor(host, PALM[0]!);
343	    // Malformed answers get no verdict at all.
344	    for (const payload of [{ requestId: "x" }, { requestId: "bad id", attempt: { kind: "sequence", symbols: ["sun"] } }, "sun,moon,tide", { requestId: "y", attempt: { kind: "sequence", symbols: ["gold"] } }]) {
345	      host.sendRaw(RuinMessageType.Answer, payload);
346	    }
347	    host.sendRaw(RuinMessageType.Open, { island: 2 });
348	    await sleep(1100);
349	    expect(host.ruinResults).toEqual([]);
350	    expect(host.clues).toEqual([]);
351	    // A burst: at most MAX_RUIN_MESSAGES_PER_SECOND (8) are read in a second.
352	    for (let index = 0; index < 20; index++) host.answerRuin({ kind: "sequence", symbols: ["sun", "moon", "tide"] }, `burst${index}`);
353	    await sleep(500);
354	    expect(host.ruinResults.length).toBeLessThanOrEqual(MAX_RUIN_MESSAGES_PER_SECOND);
355	    expect(host.ruinResults.length).toBeGreaterThan(0);
356	    expect(host.ruinResults.every((result) => result.outcome === "refused" && result.reason === "no-session")).toBe(true);
357	    // Opens count against the same cap: after a burst of opens, an answer in that second is not read.
358	    await sleep(1100);
359	    const heard = host.ruinResults.length;
360	    for (let index = 0; index < 12; index++) host.openRuin();
361	    host.answerRuin({ kind: "sequence", symbols: ["sun", "moon", "tide"] }, "after-opens");
362	    await sleep(500);
363	    expect(host.ruinResults).toHaveLength(heard);
364	    // And a real open after the second has passed still works.
