1	/**
2	 * A reader of ruin clues (§3), for tests: it works an answer out from what the site shows, as a player would, and
3	 * never from the server's puzzle. A sequence clue is read tablet by tablet (each hint rules sequences out); a grid is
4	 * walked breadth-first from the start to the goal round the blocked cells. No import beyond the protocol's names, so
5	 * browser tests can use it on a clue they read off the page.
6	 */
7	
8	export type Symbol = "sun" | "moon" | "tide" | "storm" | "anchor" | "skull";
9	export type Move = "N" | "E" | "S" | "W";
10	
11	export interface ReadHint {
12	  readonly relation: string;
13	  readonly other: string | null;
14	  readonly position: number | null;
15	}
16	
17	export interface ReadTablet {
18	  readonly symbol: string;
19	  readonly hint: ReadHint;
20	}
21	
22	export interface ReadCell {
23	  readonly x: number;
24	  readonly y: number;
25	}
26	
27	export type ReadClue =
28	  | { readonly kind: "sequence"; readonly length: number; readonly tablets: readonly ReadTablet[] }
29	  | { readonly kind: "navigation"; readonly size: number; readonly start: ReadCell; readonly goal: ReadCell; readonly blocked: readonly ReadCell[] };
30	
31	function holds(tablet: ReadTablet, order: readonly string[]): boolean {
32	  const index = order.indexOf(tablet.symbol);
33	  const other = tablet.hint.other === null ? -1 : order.indexOf(tablet.hint.other);
34	  const both = index >= 0 && other >= 0;
35	  switch (tablet.hint.relation) {
36	    case "absent":
37	      return index < 0;
38	    case "present":
39	      return index >= 0;
40	    case "at":
41	      return index >= 0 && index === tablet.hint.position;
42	    case "not-at":
43	      return index !== tablet.hint.position;
44	    case "right-after":
45	      return both && index === other + 1;
46	    case "right-before":
47	      return both && index + 1 === other;
48	    case "after":
