1	import { describe, expect, it } from "vitest";
2	import { seaMap } from "@pirate-sea-race/content";
3	import { RUIN_KIND_NAMES, RUIN_MOVE_NAMES, RUIN_SYMBOL_NAMES } from "@pirate-sea-race/protocol";
4	import { objectiveRules, unlockSource } from "@pirate-sea-race/simulation/objectives";
5	import { clueFor, createRuins, RUIN_MOVES, RUIN_SYMBOLS } from "@pirate-sea-race/simulation/ruins";
6	import { deriveSeed, MASTER_SECRET_BYTES, type SeedSystem } from "./matchSeeds.js";
7	import { createMatchLedger } from "./objectives.js";
8	import {
9	  createMatchRuins,
10	  islandCentre,
11	  islandOfDock,
12	  islandUnlocked,
13	  nearestIslandPoint,
14	  openIslandsInLedger,
15	  REMEMBERED_RUIN_REQUESTS,
16	  RUIN_PIN_TRIES,
17	  ruinIslandsOf,
18	  RuinRequests,
19	  testRuinSetting,
20	} from "./ruins.js";
21	
22	const ledger = createMatchLedger({ map: seaMap, seed: 11, rules: objectiveRules });
23	const islands = ruinIslandsOf(ledger);
24	const secretOf = (fill: number) => new Uint8Array(MASTER_SECRET_BYTES).fill(fill);
25	/** The room's derivation: the ruins' own seed first, then `ruins:<n>` only to meet a pinned kind. */
26	const seedsOf = (secret: Uint8Array) => (attempt: number) => deriveSeed(secret, attempt === 0 ? "ruins" : `ruins:${attempt}`);
27	const kinds = (ruins: ReturnType<typeof createMatchRuins>["ruins"]) => Object.values(ruins.ruins).map((ruin) => ruin.puzzle.kind);
28	
29	describe("the ruins' seed (§3, §16)", () => {
30	  it("is the ruins' own derivation of the master secret: distinct from every other system's seed, and the same for the same secret", () => {
31	    const secret = secretOf(5);
32	    const dealt = createMatchRuins({ islands, seed: seedsOf(secret) });
33	    expect(dealt.seed).toBe(deriveSeed(secret, "ruins"));
34	    expect(dealt.ruins).toEqual(createRuins({ seed: deriveSeed(secret, "ruins"), islands }));
35	    const others: SeedSystem[] = ["world", "ledger", "final-socket", "intel", "fruit", "duel:1", "ruins:1"];
36	    for (const system of others) expect(deriveSeed(secret, system)).not.toBe(dealt.seed);
37	    // Not the ledger's seed, so the clues say nothing of the rubbings' deal.
38	    const fromLedgerSeed = createRuins({ seed: deriveSeed(secret, "ledger"), islands });
39	    expect(Object.values(fromLedgerSeed.ruins).map((ruin) => clueFor(ruin))).not.toEqual(Object.values(dealt.ruins.ruins).map((ruin) => clueFor(ruin)));
40	    // The derivation reads only the secret and the system's name: no match code goes in, so matches with any codes
41	    // and the same secret deal the same ruins, and another secret deals others.
42	    expect(createMatchRuins({ islands, seed: seedsOf(secretOf(5)) }).ruins).toEqual(dealt.ruins);
43	    expect(createMatchRuins({ islands, seed: seedsOf(secretOf(6)) }).ruins).not.toEqual(dealt.ruins);
44	    expect(deriveSeed.length).toBe(2);
45	  });
46	
47	  it("gives every regular island a ruin over its ledger sources, and none opened", () => {
48	    expect(islands).toEqual([0, 1, 2, 3].map((island) => ({ island, sourceIds: [`source-${island}-0`, `source-${island}-1`] })));
49	    const dealt = createMatchRuins({ islands, seed: seedsOf(secretOf(1)) });
50	    expect(dealt.openIslands).toEqual([]);
51	    expect(Object.keys(dealt.ruins.ruins)).toEqual(["0", "1", "2", "3"]);
52	  });
53	});
54	
55	describe("the test-only ruins", () => {
56	  it("pins an island's kind by taking the first derived seed that deals it, still from the master secret", () => {
57	    for (const fill of [1, 2, 3, 4]) {
58	      const secret = secretOf(fill);
59	      for (const kind of RUIN_KIND_NAMES) {
60	        const dealt = createMatchRuins({ islands, seed: seedsOf(secret), settings: { "0": kind, "2": kind === "sequence" ? "navigation" : "sequence" } });
61	        expect(dealt.ruins.ruins["0"]!.puzzle.kind).toBe(kind);
62	        expect(dealt.ruins.ruins["2"]!.puzzle.kind).not.toBe(kind);
63	        const attempt = Array.from({ length: RUIN_PIN_TRIES }, (_, index) => index).find((index) => seedsOf(secret)(index) === dealt.seed)!;
64	        // Every earlier derived seed misses a pin.
65	        for (let earlier = 0; earlier < attempt; earlier++) {
66	          const missed = createRuins({ seed: seedsOf(secret)(earlier), islands });
67	          expect(missed.ruins["0"]!.puzzle.kind === kind && missed.ruins["2"]!.puzzle.kind !== kind).toBe(false);
68	        }
69	      }
70	    }
71	  });
72	
73	  it("opens islands from the start, by number or for the rest with *, and refuses pins no seed meets", () => {
74	    const dealt = createMatchRuins({ islands, seed: seedsOf(secretOf(2)), settings: { "*": "open", "1": "navigation" } });
75	    expect(dealt.openIslands).toEqual([0, 2, 3]);
76	    expect(dealt.ruins.ruins["1"]!.puzzle.kind).toBe("navigation");
77	    expect(testRuinSetting(undefined, 0)).toBeUndefined();
78	    expect(testRuinSetting({ "1": "open" }, 0)).toBeUndefined();
79	    const opened = openIslandsInLedger(ledger, dealt.openIslands);
80	    expect([0, 1, 2, 3].map((island) => islandUnlocked(opened, island))).toEqual([true, false, true, true]);
81	    expect([0, 1, 2, 3].map((island) => islandUnlocked(ledger, island))).toEqual([false, false, false, false]);
82	    expect(islandUnlocked(opened, 9)).toBe(false);
83	    // One source of two open is not an open island.
84	    expect(islandUnlocked(unlockSource(ledger, { sourceId: "source-1-0", tick: 0 }).state, 1)).toBe(false);
85	    // A constant seed deals the same kinds every try: asking for the other kind finds none.
86	    const constant = createRuins({ seed: 4, islands });
87	    const other = constant.ruins["0"]!.puzzle.kind === "sequence" ? "navigation" : "sequence";
88	    expect(() => createMatchRuins({ islands, seed: () => 4, settings: { "0": other } })).toThrow(/no ruins seed/);
89	    expect(kinds(createMatchRuins({ islands, seed: () => 4, settings: { "0": constant.ruins["0"]!.puzzle.kind } }).ruins)).toEqual(kinds(constant));
90	  });
91	});
92	
93	describe("the room's ruin helpers", () => {
94	  it("keeps the protocol's symbol and move names equal to the content's", () => {
95	    expect([...RUIN_SYMBOL_NAMES]).toEqual([...RUIN_SYMBOLS]);
96	    expect([...RUIN_MOVE_NAMES]).toEqual([...RUIN_MOVES]);
97	  });
98	
99	  it("finds a dock's island and an island's centre", () => {
100	    const dock = seaMap.docks.find((each) => each.island === 2)!;
101	    expect(islandOfDock(seaMap, dock.id)).toBe(2);
102	    expect(islandOfDock(seaMap, -1)).toBeNull();
103	    expect(islandOfDock({ ...seaMap, docks: [{ ...dock, island: -1 }] }, 0)).toBeNull();
104	    const rect = seaMap.islands[2]!;
105	    const centre = islandCentre(seaMap, 2);
106	    expect(centre.x).toBe(Math.floor((rect.tileX + rect.widthTiles / 2) * seaMap.subUnitsPerTile));
107	    expect(centre.y).toBe(Math.floor((rect.tileY + rect.heightTiles / 2) * seaMap.subUnitsPerTile));
108	    expect(() => islandCentre(seaMap, 99)).toThrow(/no island 99/);
109	  });
110	
111	  it("remembers each player's latest answers by request id, forgetting the oldest past the bound and a player who left", () => {
112	    const requests = new RuinRequests<number>();
113	    for (let index = 0; index <= REMEMBERED_RUIN_REQUESTS; index++) requests.remember("a", `r${index}`, index);
114	    requests.remember("b", "r0", 100);
115	    expect(requests.get("a", "r0")).toBeUndefined();
116	    expect(requests.get("a", "r1")).toBe(1);
117	    expect(requests.get("a", `r${REMEMBERED_RUIN_REQUESTS}`)).toBe(REMEMBERED_RUIN_REQUESTS);
118	    expect(requests.get("b", "r0")).toBe(100);
119	    requests.forget("a");
120	    expect(requests.get("a", "r1")).toBeUndefined();
121	    expect(requests.get("b", "r0")).toBe(100);
122	  });
123	});
124	
125	describe("an island in sight", () => {
126	  it("is measured to the island's nearest point, so a ship off its shore sees it", () => {
127	    const rect = seaMap.islands[0]!;
128	    const tile = seaMap.subUnitsPerTile;
129	    expect(nearestIslandPoint(seaMap, 0, 0, 0)).toEqual({ x: rect.tileX * tile, y: rect.tileY * tile });
