/** A stand-in for the page's banner fields: plain objects with what `showBanner` touches. */
function bannerPage() {
  const element = () => ({ hidden: true, textContent: "", dataset: {} as Record<string, string>, children: [] as unknown[], append(...items: unknown[]) { this.children.push(...items); } });
  const fields = { banner: element(), "banner-title": element(), "banner-detail": element(), "reveal-log": element() };
  const root = { querySelector: (selector: string) => fields[/data-testid="([^"]+)"/.exec(selector)![1] as keyof typeof fields] ?? null } as unknown as ParentNode;
  return { root, fields };
}

describe("the reveals' banner over the sea (showBanner, BANNER_MS)", () => {
  afterEach(() => {
    vi.useRealTimers();
    vi.unstubAllGlobals();
  });

  function withFakePage() {
    vi.useFakeTimers();
    vi.stubGlobal("window", globalThis);
    vi.stubGlobal("document", { createElement: () => ({ dataset: {}, textContent: "" }) });
    return bannerPage();
  }

  it("hides itself BANNER_MS after a reveal, and logs every reveal", () => {
    const { root, fields } = withFakePage();
    const timers: { hide?: number } = {};
    showBanner(root, { kind: "final-sector", tone: "treasure", title: "A full set of rubbings exists!", detail: "Northern Waters" }, timers);
    expect(fields.banner.hidden).toBe(false);
    expect(fields["banner-title"].textContent).toBe("A full set of rubbings exists!");
    vi.advanceTimersByTime(BANNER_MS - 1);
    expect(fields.banner.hidden).toBe(false);
    vi.advanceTimersByTime(1);
    expect(fields.banner.hidden).toBe(true);
    expect(fields["reveal-log"].children).toHaveLength(1);
  });

  it("re-arms its hide when a new reveal arrives, so the newer banner stays its whole BANNER_MS", () => {
    const { root, fields } = withFakePage();
    const timers: { hide?: number } = {};
    showBanner(root, { kind: "final-sector", tone: "treasure", title: "First", detail: "" }, timers);
    vi.advanceTimersByTime(BANNER_MS - 1000);
    showBanner(root, { kind: "sector-reveal", tone: "info", title: "Second", detail: "" }, timers);
    // The first banner's hide would have come now: the second is still up.
    vi.advanceTimersByTime(1000);
    expect(fields.banner.hidden).toBe(false);
    expect(fields["banner-title"].textContent).toBe("Second");
    vi.advanceTimersByTime(BANNER_MS - 1001);
    expect(fields.banner.hidden).toBe(false);
    vi.advanceTimersByTime(1);
    expect(fields.banner.hidden).toBe(true);
    expect(fields["reveal-log"].children).toHaveLength(2);
  });
});

